package com.shms.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="lab_results") public class LabResult {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="lab_order_id",nullable=false,unique=true) private LabOrder labOrder;
 @Column(name="result_value") private String resultValue; private String unit; @Column(name="reference_range") private String referenceRange; @Column(name="result_text",columnDefinition="TEXT") private String resultText; @Column(name="attachment_url") private String attachmentUrl;
 @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="verified_by") private User verifiedBy; @Column(name="verified_at") private LocalDateTime verifiedAt; @Column(name="created_at") private LocalDateTime createdAt;
 @PrePersist void pre(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public void setId(Long v){id=v;} public LabOrder getLabOrder(){return labOrder;} public void setLabOrder(LabOrder v){labOrder=v;} public String getResultValue(){return resultValue;} public void setResultValue(String v){resultValue=v;} public String getUnit(){return unit;} public void setUnit(String v){unit=v;} public String getReferenceRange(){return referenceRange;} public void setReferenceRange(String v){referenceRange=v;} public String getResultText(){return resultText;} public void setResultText(String v){resultText=v;} public String getAttachmentUrl(){return attachmentUrl;} public void setAttachmentUrl(String v){attachmentUrl=v;} public User getVerifiedBy(){return verifiedBy;} public void setVerifiedBy(User v){verifiedBy=v;} public LocalDateTime getVerifiedAt(){return verifiedAt;} public void setVerifiedAt(LocalDateTime v){verifiedAt=v;} public LocalDateTime getCreatedAt(){return createdAt;}
}
